#!/usr/bin/env python3
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1]
items=[
('bedtimecoach','BedtimeCoach','https://bedtimecoach.com/','$19 one-time; optional support $4.99/month','Instant printable PDF plus log; questionnaire on age, room, difficulty and method, including daycare variant. Five age bands are disclosed.','printable PDF + sleep log','No public customer reviews or success counts: seller explicitly describes itself as new. Not proof of any purchase.','Age-band rules plus stated family constraints become a plan'),
('dawnly','Dawnly Sleep','https://dawnlysleep.com/','$67 one-time; terms mention optional $19 printable toolkit','Eight questions; sleep-profile interpretation, sixty-page playbook and fourteen-day schedule in one PDF, instant email delivery. Seller advertises thirty-day fit-based refund.','One PDF, delivered to your inbox in seconds.','Seller testimonials are neither independent reviews nor verified transactions. Root-cause/diagnosis, cortisol, efficacy and safety assertions are unverified seller claims, not adopted guidance.','Eight answers select a profile and fourteen-day plan'),
('sweetsiestas','Sweet Siestas','https://www.sweetsiestasllc.com/sleep-packages','$225 / $375 / $525; higher twin packages','All packages include sixty-minute call, personalized plan, sleep log, email/text support and Fundamentals PDF; support duration changes with price.','3 days of email or text support','Service bundle. Cannot allocate listed price to the personalized document. No independent buyer or receipt examined.','A call and follow-up accompany the written plan'),
('nested','Nested Sleep','https://nestedsleep.com/services/','$649 / $849 / $1399','Intake, sixty-minute interview, nursery assessment, emailed PDF, logs, follow-up calls and support; ages four months to eighteen years exceed target niche.','Emailed personalized sleep plan (PDF)','Service bundle. Claimed 95% improvement, FSA eligibility and credentials not independently verified; not report-only pricing or proof of sales.','Assessment and continuing professional support accompany a PDF'),
('babysleepandsmile','Baby Sleep & Smile','https://babysleepandsmile.com/personalized-sleep-plan/','Not displayed on inspected page','English-language UAE service; questionnaire, personalized written plan, daily WhatsApp support and revisions. Newborn to six years stated.','Daily support during implementation','English page is a global comparator, not evidence of UK/US/CA/AU customers. Consultation/support bundle, no independent transaction or verified safety/efficacy.','Family questionnaire becomes written guidance and ongoing adjustments'),
('pittsburgh','Riverbend Birth sleep counseling','https://www.pittsburghbirthservices.com/pittsburgh-online-sleep-consultant-infants-toddlers','$550 DIY / $850 Basic / $1450 Comprehensive','Even DIY includes intake, emailed personalized PDF, one-to-two-hour planning session and two thirty-minute support sessions. Higher packages add daily and emotional/lifestyle support.','DIY Package: $550','Seller-hosted testimonials and clinical/safety assertions unverified. DIY is still a human service bundle; its price cannot establish report-only willingness to pay.','Intake and planning sessions produce a supported PDF')]
voice=[];ledger=[]
for name,title,url,price,fmt,quote,limit,mechanism in items:
 raw=f'_raw/market-wave-03/pages/{name}.txt';text=(R/raw).read_text();assert quote in text and len(quote.split())<=25
 i=f'mkt05-{len(voice)+1:04}';voice.append({'id':i,'source':title+' — current public seller offer','url':url,'date':'2026-10-24','speaker':'advisor','stage':'unknown','type':'advice_given','themes':['sleep_routines','personalization','portable_formats','price_value'],'quote':quote,'context':'Current advertised seller offer; price, delivered quality, transactions and claimed outcomes are not independently verified.','raw_file':raw,'source_class':'competitor','evidence_kind':'seller_claim'})
 note=f'# {title}\n\nPublic offer fully read 2026-10-24. Source: [{title}]({url}); frozen full text `{raw}` with original HTML and headers alongside.\n\nMechanism (≤8 words): {mechanism}\n\nAdvertised price: {price}. Symbols/currencies exactly as displayed; no checkout or conversion tested.\n\nFormat and personalization: {fmt}\n\nProof limits: {limit}\n\nVerbatim [{i}]:\n\n> {quote}\n\nInterpretation: establishes supply of personalized written sleep guidance. Only the first two offers are clear document-led purchases without a required consultation. No product bought, questionnaire submitted, account created, contact made or parent data entered. This is competitor research, not an instruction to build a sleep product.\n'
 # Final interpretation is source-specific, not universal first-two ambiguity.
 note=note.replace('Only the first two offers are clear document-led purchases without a required consultation.','This offer is document-led without a required consultation.' if name in ['bedtimecoach','dawnly'] else 'This offer bundles human support with the document.')
 (R/f'competitors/wave03-{name}.md').write_text(note)
 ledger.append({'name':name,'url':url,'raw_file':raw,'full_offer_read':True,'quote_ids':[i],'sha256':hashlib.sha256((R/raw).read_bytes()).hexdigest(),'evidence_kind':'seller_claim','new_competitor_note':True})
for name,raw,url in [('kinedu-assessment','_raw/market-wave-03/pages/kinedu-assessment.txt','https://www.kinedu.com/assessment'),('mymatleave','_raw/market-wave-03/pages/mymatleave-rendered.json','https://mymatleave.com/')]:ledger.append({'name':name,'url':url,'raw_file':raw,'full_offer_read':True,'quote_ids':[],'sha256':hashlib.sha256((R/raw).read_bytes()).hexdigest(),'evidence_kind':'seller_claim','new_competitor_note':False,'note':'Reinspection of existing competitor; current price and format confirmed, no extra quotation.'})
ledger.append({'name':'iloveyoumore','url':'https://www.iloveyoumoresleepsolutions.com/sleep-services/custom-sleep-plan','raw_file':'_raw/market-wave-03/pages/iloveyoumore.txt','full_offer_read':False,'status':'404 Site not found; search result stale or unreachable, no offer/pricing claim carried forward'})
(R/'voice/market-05.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in voice));(R/'sources/market-wave-03-reading.jsonl').write_text(''.join(json.dumps(x)+'\n' for x in ledger));print({'new_notes':len(items),'new_quotes':len(voice),'fully_read_offers':8,'failed_offer':1})
